design_artifacts.class_diagram_mermaid:
```mermaid
classDiagram
    class Expression {
        -raw_input: str
        -parsed_tokens: list
        -result: float
        +__init__(raw_input: str)
        +parse()
        +evaluate()
    }
    class Operator {
        -symbol: str
        -precedence: int
        +__init__(symbol: str)
        +apply(left: float, right: float) -> float
    }
    class CalculationResult {
        -value: float
        -formatted: str
        +__init__(value: float)
        +__str__() -> str
    }
    class ErrorMessage {
        -message: str
        -error_type: str
        +__init__(message: str, error_type: str)
        +__str__() -> str
    }
    class ExpressionParser {
        +parse(expression: str) -> list
    }
    class CalculatorEngine {
        +evaluate(tokens: list) -> float
    }
    class OutputFormatter {
        +format_result(value: float) -> str
        +format_error(error: Exception) -> str
    }
    class Calculator {
        -parser: ExpressionParser
        -engine: CalculatorEngine
        -formatter: OutputFormatter
        +__init__()
        +calculate(expression: str) -> str
    }
    class CalculatorApp {
        -calculator: Calculator
        +__init__()
        +run()
    }
    ExpressionParser --> Expression : produces
    CalculatorEngine --> Operator : uses
    Calculator --> ExpressionParser
    Calculator --> CalculatorEngine
    Calculator --> OutputFormatter
    CalculatorApp --> Calculator
```

